#!/bin/sh
# Generate src/explorer_css.or and src/explorer_js.or from theme/explorer.css and theme/explorer.js (the readable sources of
# the two static assets the explorer writes next to every site). The assets are embedded as string literals; the generated
# files are never edited by hand. Usage: tooling/explorer/gen_assets.sh [--check]
#   --check  exit 1 when a generated file is not what the generator would write
set -eu
cd "$(dirname "$0")"
tmp=$(mktemp)
trap 'rm -f "$tmp"' EXIT
status=0
# gen SOURCE OUTPUT CONSTANT
gen() {
  if grep -q '["\\]' "$1"; then
    echo "gen_assets: $1 must not contain a double quote or a backslash (use single quotes)" >&2
    exit 1
  fi
  {
    echo "// GENERATED by tooling/explorer/gen_assets.sh from $1. Do not edit; edit the source and regenerate."
    echo
    printf 'export const %s: string = "' "$3"
    awk 'BEGIN { first = 1 } { if (!first) printf "\\n"; first = 0; printf "%s", $0 } END { printf "\\n" }' "$1"
    echo '";'
  } > "$tmp"
  if [ "${CHECK:-}" = 1 ]; then
    cmp -s "$tmp" "$2" || { echo "gen_assets: $2 is stale; run tooling/explorer/gen_assets.sh" >&2; status=1; }
  else
    cp "$tmp" "$2"
  fi
}
[ "${1:-}" != "--check" ] || CHECK=1
gen theme/explorer.css src/explorer_css.or EXPLORER_CSS
gen theme/explorer.js src/explorer_js.or EXPLORER_JS
gen theme/business.css src/business_css.or BUSINESS_CSS
gen theme/runs.css src/runs_css.or RUNS_CSS
exit $status
